import { TOPICS, p, ref, snip, t, type TaskSeed } from "./define";

type AdvSeed = Omit<TaskSeed, "backlog" | "status" | "claimable" | "deps" | "readFirst" | "analyze"> & {
  blocks: string[];
  integratesWith?: string[];
  readFirst?: string[];
  analyze?: string[];
};

/**
 * Advanced backlog: valuable follow-on work that stays in Backlog (not claimable) until
 * its hard prerequisites are approved.
 */
function adv(a: AdvSeed): TaskSeed {
  const { blocks, integratesWith = [], readFirst, analyze, ...rest } = a;
  return {
    ...rest,
    backlog: "advanced",
    status: "backlog",
    claimable: false,
    labels: [...new Set([...(a.labels ?? []), "advanced"])],
    readFirst: readFirst ?? a.resources.slice(0, 3).map(([, , why]) => why),
    analyze: analyze ?? ["Which assumptions from the prerequisite tasks does this depend on?", "What is the smallest experiment that shows the approach is worth pursuing?", "What result would make you stop and recommend against it?"],
    deps: [
      ...blocks.map((k) => [k, "blocks", `${k} must be approved before this work is meaningful.`] as [string, "blocks", string]),
      ...integratesWith.map((k) => [k, "integrates", `Shares interfaces with ${k}.`] as [string, "integrates", string]),
    ],
  };
}

